-- Least-privilege PostgreSQL roles for WalkTogether (run once per environment as the RDS master user;
-- the master credentials are then locked away and never used by the application).
--
--   wt_migrator : owns the schema; used ONLY by the release migration job (DDL).
--   wt_app      : the API and worker; DML on application tables, no DDL, cannot alter audit history.
--   wt_readonly : analysts / support tooling; SELECT on non-sensitive views only (grant explicitly).
--
-- Passwords are generated by Terraform/Secrets Manager and set with ALTER ROLE … PASSWORD from a
-- secure session; they are never written into this file. All roles must connect over TLS
-- (rds.force_ssl = 1) and pg_hba on self-hosted servers must use hostssl + scram-sha-256.

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'wt_migrator') THEN CREATE ROLE wt_migrator LOGIN NOINHERIT; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'wt_app') THEN CREATE ROLE wt_app LOGIN NOINHERIT; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'wt_readonly') THEN CREATE ROLE wt_readonly LOGIN NOINHERIT; END IF;
END $$;

ALTER ROLE wt_app SET statement_timeout = '30s';
ALTER ROLE wt_app SET idle_in_transaction_session_timeout = '60s';
ALTER ROLE wt_readonly SET default_transaction_read_only = on;

DO $$ BEGIN
  EXECUTE format('REVOKE ALL ON DATABASE %I FROM PUBLIC', current_database());
  EXECUTE format('GRANT CONNECT ON DATABASE %I TO wt_migrator, wt_app, wt_readonly', current_database());
END $$;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;

-- The migrator owns everything it creates.
GRANT ALL ON SCHEMA public TO wt_migrator;
GRANT USAGE, CREATE ON SCHEMA gps_partitions TO wt_migrator;

-- Application: read/write data, no DDL.
GRANT USAGE ON SCHEMA public, gps_partitions TO wt_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public, gps_partitions TO wt_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO wt_app;
GRANT EXECUTE ON FUNCTION gps_partitions.ensure_partitions(date, int) TO wt_app;
ALTER DEFAULT PRIVILEGES FOR ROLE wt_migrator IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO wt_app;
ALTER DEFAULT PRIVILEGES FOR ROLE wt_migrator IN SCHEMA public GRANT USAGE, SELECT ON SEQUENCES TO wt_app;
ALTER DEFAULT PRIVILEGES FOR ROLE wt_migrator IN SCHEMA gps_partitions GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO wt_app;

-- Audit and financial history: the application may append but never rewrite or delete
-- (database triggers enforce the same rule even for the migrator).
REVOKE UPDATE, DELETE, TRUNCATE ON audit_logs, invoices FROM wt_app;
REVOKE DELETE, TRUNCATE ON payments FROM wt_app;
REVOKE TRUNCATE ON ALL TABLES IN SCHEMA public FROM wt_app;

-- Read-only role: nothing by default; grant specific reporting views when they exist.
GRANT USAGE ON SCHEMA public TO wt_readonly;
